.vbp-pricing-sim-container {
    padding: 24px;
    background: #f4f6f9;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}

.vbp-pricing-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2d4055 70%, #324a63 100%);
    color: #f4f6f9;
    border-radius: 6px;
    padding: 26px 30px;
    margin-bottom: 24px;
    border-left: 5px solid #d4a017;
    box-shadow: 0 4px 14px rgba(26,39,68,0.10);
}
.vbp-pricing-sim-header-content {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 24px;
    flex-wrap: wrap;
}
.vbp-pricing-sim-eyebrow {
    color: #d4a017;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    font-weight: 700;
    margin-bottom: 6px;
}
.vbp-pricing-sim-header h1 {
    color: #ffffff;
    font-size: 1.55rem;
    margin: 0 0 8px 0;
    font-weight: 700;
    letter-spacing: -0.01em;
    line-height: 1.2;
}
.vbp-pricing-sim-header p {
    color: #b8c5d6;
    font-size: 0.88rem;
    margin: 0;
    font-weight: 400;
}
.vbp-pricing-sim-period-counter {
    background: rgba(212,160,23,0.12);
    border: 1px solid rgba(212,160,23,0.4);
    padding: 12px 20px;
    border-radius: 4px;
    color: #d4a017;
    font-weight: 600;
    text-align: right;
    min-width: 200px;
}
.vbp-pricing-sim-period-line {
    font-size: 1.05rem;
    color: #ffffff;
    font-weight: 700;
}
.vbp-pricing-sim-period-line span:nth-child(2),
.vbp-pricing-sim-period-line span:nth-child(4) {
    color: #d4a017;
    margin: 0 4px;
}
.vbp-pricing-sim-round {
    color: #b8c5d6;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-top: 8px;
    font-weight: 600;
}

.vbp-pricing-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.vbp-pricing-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #e1e5eb;
    border-top: 3px solid #2d4055;
    padding: 18px 18px;
    border-radius: 4px;
    transition: box-shadow 0.2s ease, transform 0.2s ease;
}
.vbp-pricing-sim-kpi-card:hover {
    box-shadow: 0 6px 18px rgba(26,39,68,0.10);
    transform: translateY(-2px);
}
.vbp-pricing-sim-kpi-primary {
    border-top-color: #d4a017;
    background: linear-gradient(180deg, #fffbf0 0%, #ffffff 60%);
}
.vbp-pricing-sim-kpi-label {
    color: #6b7280;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 10px;
    font-weight: 600;
}
.vbp-pricing-sim-kpi-value {
    font-size: 1.8rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
    font-variant-numeric: tabular-nums;
}
.vbp-pricing-sim-kpi-primary .vbp-pricing-sim-kpi-value {
    color: #b8860b;
    font-size: 2rem;
}

.vbp-pricing-sim-main-grid {
    display: grid;
    grid-template-columns: 1.4fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
}

.vbp-pricing-sim-briefing,
.vbp-pricing-sim-controls,
.vbp-pricing-sim-charts,
.vbp-pricing-sim-history {
    background: #ffffff;
    border: 1px solid #e1e5eb;
    border-radius: 6px;
    padding: 22px 24px;
}
.vbp-pricing-sim-briefing h3,
.vbp-pricing-sim-controls h3,
.vbp-pricing-sim-charts h3,
.vbp-pricing-sim-history h3 {
    color: #1a2744;
    font-size: 0.85rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin: 0 0 16px 0;
    padding-bottom: 12px;
    border-bottom: 2px solid #e1e5eb;
}

.vbp-pricing-sim-customer-card {
    background: #f9fafc;
    border: 1px solid #e1e5eb;
    border-left: 4px solid #d4a017;
    padding: 18px 20px;
    border-radius: 4px;
    margin-bottom: 16px;
}
.vbp-pricing-sim-customer-head {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
}
.vbp-pricing-sim-customer-name {
    font-size: 1.3rem;
    font-weight: 700;
    color: #1a2744;
    letter-spacing: -0.01em;
}
.vbp-pricing-sim-segment-pill {
    background: #1a2744;
    color: #d4a017;
    padding: 5px 14px;
    border-radius: 14px;
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.08em;
}
.vbp-pricing-sim-customer-meta {
    color: #4a5568;
    font-size: 0.85rem;
    margin-top: 6px;
    font-weight: 500;
}
.vbp-pricing-sim-badges {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    margin-top: 14px;
}
.vbp-pricing-sim-badge {
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    padding: 5px 11px;
    border-radius: 3px;
    background: #e1e5eb;
    color: #4a5568;
}
.vbp-pricing-sim-badge-good {
    background: #d1f7e0;
    color: #0d7c3f;
}
.vbp-pricing-sim-badge-warn {
    background: #fdf2d4;
    color: #97700b;
}
.vbp-pricing-sim-badge-bad {
    background: #fde0db;
    color: #c83e2c;
}
.vbp-pricing-sim-customer-narrative {
    margin-top: 14px;
    color: #2d3748;
    font-size: 0.86rem;
    line-height: 1.6;
    padding-top: 14px;
    border-top: 1px dashed #d8dde5;
}

.vbp-pricing-sim-eve-block {
    background: #fffbf0;
    border: 1px solid #f0e0a8;
    border-radius: 4px;
    padding: 16px 18px;
}
.vbp-pricing-sim-eve-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    padding-bottom: 10px;
    border-bottom: 2px solid #d4a017;
    margin-bottom: 12px;
}
.vbp-pricing-sim-eve-header > span:first-child {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #97700b;
    font-weight: 700;
}
.vbp-pricing-sim-eve-amount {
    font-size: 1.5rem;
    font-weight: 700;
    color: #b8860b;
    font-variant-numeric: tabular-nums;
}
.vbp-pricing-sim-waterfall {
    font-size: 0.82rem;
}
.vbp-pricing-sim-wf-row {
    display: flex;
    justify-content: space-between;
    padding: 5px 0;
    color: #2d3748;
    font-variant-numeric: tabular-nums;
}
.vbp-pricing-sim-wf-sub {
    border-top: 1px solid #e1e5eb;
    border-bottom: 1px solid #e1e5eb;
    margin: 5px 0;
    padding: 7px 0;
    font-weight: 600;
    color: #1a2744;
}
.vbp-pricing-sim-wf-total {
    border-top: 2px solid #1a2744;
    margin-top: 7px;
    padding-top: 9px;
    font-weight: 700;
    color: #b8860b;
    font-size: 0.95rem;
}

.vbp-pricing-sim-controls {
    display: flex;
    flex-direction: column;
}
.vbp-pricing-sim-field {
    margin-bottom: 18px;
}
.vbp-pricing-sim-field label {
    display: block;
    color: #1a2744;
    font-size: 0.78rem;
    font-weight: 700;
    margin-bottom: 8px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.vbp-pricing-sim-controls select,
.vbp-pricing-sim-controls input[type="number"] {
    width: 100%;
    background: #ffffff;
    border: 1px solid #cbd2dc;
    color: #1a2744;
    border-radius: 4px;
    padding: 11px 13px;
    font-size: 0.95rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.vbp-pricing-sim-controls select:focus,
.vbp-pricing-sim-controls input[type="number"]:focus {
    border-color: #d4a017;
    box-shadow: 0 0 0 3px rgba(212,160,23,0.18);
    outline: none;
}
.vbp-pricing-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}
.vbp-pricing-sim-hint {
    font-size: 0.75rem;
    color: #6b7280;
    margin-top: 6px;
    line-height: 1.45;
    font-style: italic;
}
.vbp-pricing-sim-actions {
    display: flex;
    gap: 10px;
    margin-top: 8px;
    flex-wrap: wrap;
}
.vbp-pricing-sim-controls .btn-primary {
    background: #1a2744;
    border-color: #1a2744;
    color: #ffffff;
    font-weight: 700;
    padding: 12px 24px;
    border-radius: 4px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.82rem;
    flex: 1;
    transition: background 0.2s ease;
}
.vbp-pricing-sim-controls .btn-primary:hover {
    background: #d4a017;
    border-color: #d4a017;
    color: #1a2744;
}
.vbp-pricing-sim-controls .btn-outline-secondary {
    border: 1px solid #cbd2dc;
    color: #4a5568;
    background: #ffffff;
    font-size: 0.78rem;
    padding: 12px 16px;
    border-radius: 4px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-weight: 600;
}
.vbp-pricing-sim-controls .btn-outline-secondary:hover {
    background: #f4f6f9;
    color: #1a2744;
}

.vbp-pricing-sim-charts {
    margin-bottom: 24px;
}
.vbp-pricing-sim-chart-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
}
.vbp-pricing-sim-chart-wrap {
    height: 290px;
    background: #f9fafc;
    border-radius: 4px;
    padding: 14px;
    border: 1px solid #e1e5eb;
}

.vbp-pricing-sim-history table {
    font-size: 0.85rem;
    width: 100%;
    margin-bottom: 0;
}
.vbp-pricing-sim-history thead th {
    background: #1a2744;
    color: #f4f6f9;
    font-weight: 600;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 11px 14px;
    border: none;
}
.vbp-pricing-sim-history tbody td {
    padding: 9px 14px;
    border-bottom: 1px solid #e1e5eb;
    color: #2d3748;
    font-variant-numeric: tabular-nums;
}
.vbp-pricing-sim-history tbody tr:hover {
    background: #f9fafc;
}

@media (max-width: 768px) {
    .vbp-pricing-sim-container { padding: 14px; }
    .vbp-pricing-sim-main-grid { grid-template-columns: 1fr; }
    .vbp-pricing-sim-chart-grid { grid-template-columns: 1fr; }
    .vbp-pricing-sim-header h1 { font-size: 1.25rem; }
    .vbp-pricing-sim-kpi-value { font-size: 1.45rem; }
    .vbp-pricing-sim-kpi-primary .vbp-pricing-sim-kpi-value { font-size: 1.6rem; }
    .vbp-pricing-sim-period-counter { text-align: left; min-width: 0; width: 100%; }
}


/* v1.1.0 additions: accessible focus ring + completion summary */
.vbp-pricing-sim-container :is(select, input, button):focus-visible { outline: 3px solid #b8860b; outline-offset: 2px; }
.vbp-completion { color: #1a2744; padding: 8px 4px; text-align: center; }
.vbp-completion-title { color: #b8860b; margin: 0 0 12px; font-size: 1.4rem; }
.vbp-completion-score { margin: 6px 0 16px; }
.vbp-completion-score .acs-num { font-size: 2.6rem; font-weight: 700; color: #0d7c3f; }
.vbp-completion-score .acs-max { font-size: 1.1rem; color: #4a5568; margin-left: 2px; }
.vbp-completion-score .acs-cap { font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; color: #4a5568; margin-top: 2px; }
.vbp-completion-kpis { display: flex; gap: 12px; justify-content: center; margin: 12px 0 16px; flex-wrap: wrap; }
.vbp-completion-kpis .ack { background: #f4f6f9; border: 1px solid #e1e5eb; border-radius: 10px; padding: 10px 14px; min-width: 104px; }
.vbp-completion-kpis .ack-label { font-size: .66rem; text-transform: uppercase; letter-spacing: .05em; color: #4a5568; margin-bottom: 4px; }
.vbp-completion-kpis .ack-value { font-size: 1.2rem; font-weight: 600; color: #1a2744; }
.vbp-completion-rating { color: #2d3a56; margin: 10px auto; max-width: 580px; line-height: 1.5; }
.vbp-completion-takeaways { text-align: left; max-width: 660px; margin: 14px auto 0; }
.vbp-completion-takeaways h4 { color: #b8860b; font-size: .95rem; margin: 0 0 8px; }
.vbp-completion-takeaways ul { margin: 0; padding-left: 20px; }
.vbp-completion-takeaways li { margin-bottom: 6px; color: #2d3a56; line-height: 1.45; }
.vbp-completion-thanks { color: #4a5568; font-size: .85rem; margin-top: 16px; }

